from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface


class AlarmInterface(BaseClToolInterface):

    def get_active_alarms(self, timeout='15min', **kwargs):
        """Gets active alarms.

        kwarg values for Get Active Alarms
        nolog - boolean - set to True to prevent the tool from creating log file

        :return Path(s) of collected file(s).
        :rtype list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout,
                                               operation='getactivealarms', params=params, trs_ip=ne, flags=flags)

    def get_alarm_history(self, timeout='15min', **kwargs):
        """Gets raw alarm history from site.

        :return Path(s) of collected file(s).
        :rtype list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout,
                                               operation='getalarmhistory', params=params, trs_ip=ne, flags=flags)

    def check_power_alarms(self, alarm_file=None, timeout='5min', **kwargs):
        """Checks power alarms from one or multiple sites.

        :param string alarm_file: Path to the alarm file. If None, default value is ./conf/BTS_Power_Alarms.txt
        :param string ne: If None, BTSSM scans for eNB TRS IP

        :return Path(s) of collected file(s).
        :rtype list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        symlink, alarm_file = [None, alarm_file] if alarm_file else ['conf', '/opt/btssm_cli_tools/conf/BTS_Power_Alarms.txt']
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'alarmfile': alarm_file, 'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='checkalarms',
                                               params=params, trs_ip=ne, flags=flags, symlink=symlink)
